// generated by tools/build_verse_manifests.js from dc_english.js — Dual-view English for the chapters of dc_verses/dc81_90.js
registerEnglish([["D&C",81,1,"Verily, verily, I say unto you my servant Frederick G. Williams: Listen to the voice of him who speaketh, to the word of the Lord your God, and hearken to the calling wherewith you are called, even to be a high priest in my church, and a counselor unto my servant Joseph Smith, Jun.;"],["D&C",81,2,"Unto whom I have given the keys of the kingdom, which belong always unto the Presidency of the High Priesthood:"],["D&C",81,3,"Therefore, verily I acknowledge him and will bless him, and also thee, inasmuch as thou art faithful in counsel, in the office which I have appointed unto you, in prayer always, vocally and in thy heart, in public and in private, also in thy ministry in proclaiming the gospel in the land of the living, and among thy brethren."],["D&C",81,4,"And in doing these things thou wilt do the greatest good unto thy fellow beings, and wilt promote the glory of him who is your Lord."],["D&C",81,5,"Wherefore, be faithful; stand in the office which I have appointed unto you; succor the weak, lift up the hands which hang down, and strengthen the feeble knees."],["D&C",81,6,"And if thou art faithful unto the end thou shalt have a crown of immortality, and eternal life in the mansions which I have prepared in the house of my Father."],["D&C",81,7,"Behold, and lo, these are the words of Alpha and Omega, even Jesus Christ. Amen."],["D&C",82,1,"Verily, verily, I say unto you, my servants, that inasmuch as you have forgiven one another your trespasses, even so I, the Lord, forgive you."],["D&C",82,2,"Nevertheless, there are those among you who have sinned exceedingly; yea, even all of you have sinned; but verily I say unto you, beware from henceforth, and refrain from sin, lest sore judgments fall upon your heads."],["D&C",82,3,"For of him unto whom much is given much is required; and he who sins against the greater light shall receive the greater condemnation."],["D&C",82,4,"Ye call upon my name for revelations, and I give them unto you; and inasmuch as ye keep not my sayings, which I give unto you, ye become transgressors; and justice and judgment are the penalty which is affixed unto my law."],["D&C",82,5,"Therefore, what I say unto one I say unto all: Watch, for the adversary spreadeth his dominions, and darkness reigneth;"],["D&C",82,6,"And the anger of God kindleth against the inhabitants of the earth; and none doeth good, for all have gone out of the way."],["D&C",82,7,"And now, verily I say unto you, I, the Lord, will not lay any sin to your charge; go your ways and sin no more; but unto that soul who sinneth shall the former sins return, saith the Lord your God."],["D&C",82,8,"And again, I say unto you, I give unto you a new commandment, that you may understand my will concerning you;"],["D&C",82,9,"Or, in other words, I give unto you directions how you may act before me, that it may turn to you for your salvation."],["D&C",82,10,"I, the Lord, am bound when ye do what I say; but when ye do not what I say, ye have no promise."],["D&C",82,11,"Therefore, verily I say unto you, that it is expedient for my servants Edward Partridge and Newel K. Whitney, A. Sidney Gilbert and Sidney Rigdon, and my servant Joseph Smith, and John Whitmer and Oliver Cowdery, and W. W. Phelps and Martin Harris to be bound together by a bond and covenant that cannot be broken by transgression, except judgment shall immediately follow, in your several stewardships—"],["D&C",82,12,"To manage the affairs of the poor, and all things pertaining to the bishopric both in the land of Zion and in the land of Kirtland;"],["D&C",82,13,"For I have consecrated the land of Kirtland in mine own due time for the benefit of the saints of the Most High, and for a stake to Zion."],["D&C",82,14,"For Zion must increase in beauty, and in holiness; her borders must be enlarged; her stakes must be strengthened; yea, verily I say unto you, Zion must arise and put on her beautiful garments."],["D&C",82,15,"Therefore, I give unto you this commandment, that ye bind yourselves by this covenant, and it shall be done according to the laws of the Lord."],["D&C",82,16,"Behold, here is wisdom also in me for your good."],["D&C",82,17,"And you are to be equal, or in other words, you are to have equal claims on the properties, for the benefit of managing the concerns of your stewardships, every man according to his wants and his needs, inasmuch as his wants are just—"],["D&C",82,18,"And all this for the benefit of the church of the living God, that every man may improve upon his talent, that every man may gain other talents, yea, even an hundred fold, to be cast into the Lord's storehouse, to become the common property of the whole church—"],["D&C",82,19,"Every man seeking the interest of his neighbor, and doing all things with an eye single to the glory of God."],["D&C",82,20,"This order I have appointed to be an everlasting order unto you, and unto your successors, inasmuch as you sin not."],["D&C",82,21,"And the soul that sins against this covenant, and hardeneth his heart against it, shall be dealt with according to the laws of my church, and shall be delivered over to the buffetings of Satan until the day of redemption."],["D&C",82,22,"And now, verily I say unto you, and this is wisdom, make unto yourselves friends with the mammon of unrighteousness, and they will not destroy you."],["D&C",82,23,"Leave judgment alone with me, for it is mine and I will repay. Peace be with you; my blessings continue with you."],["D&C",82,24,"For even yet the kingdom is yours, and shall be forever, if you fall not from your steadfastness. Even so. Amen."],["D&C",83,1,"Verily, thus saith the Lord, in addition to the laws of the church concerning women and children, those who belong to the church, who have lost their husbands or fathers:"],["D&C",83,2,"Women have claim on their husbands for their maintenance, until their husbands are taken; and if they are not found transgressors they shall have fellowship in the church."],["D&C",83,3,"And if they are not faithful they shall not have fellowship in the church; yet they may remain upon their inheritances according to the laws of the land."],["D&C",83,4,"All children have claim upon their parents for their maintenance until they are of age."],["D&C",83,5,"And after that, they have claim upon the church, or in other words upon the Lord's storehouse, if their parents have not wherewith to give them inheritances."],["D&C",83,6,"And the storehouse shall be kept by the consecrations of the church; and widows and orphans shall be provided for, as also the poor. Amen."],["D&C",84,1,"A revelation of Jesus Christ unto his servant Joseph Smith, Jun., and six elders, as they united their hearts and lifted their voices on high."],["D&C",84,2,"Yea, the word of the Lord concerning his church, established in the last days for the restoration of his people, as he has spoken by the mouth of his prophets, and for the gathering of his saints to stand upon Mount Zion, which shall be the city of New Jerusalem."],["D&C",84,3,"Which city shall be built, beginning at the temple lot, which is appointed by the finger of the Lord, in the western boundaries of the State of Missouri, and dedicated by the hand of Joseph Smith, Jun., and others with whom the Lord was well pleased."],["D&C",84,4,"Verily this is the word of the Lord, that the city New Jerusalem shall be built by the gathering of the saints, beginning at this place, even the place of the temple, which temple shall be reared in this generation."],["D&C",84,5,"For verily this generation shall not all pass away until an house shall be built unto the Lord, and a cloud shall rest upon it, which cloud shall be even the glory of the Lord, which shall fill the house."],["D&C",84,6,"And the sons of Moses, according to the Holy Priesthood which he received under the hand of his father-in-law, Jethro;"],["D&C",84,7,"And Jethro received it under the hand of Caleb;"],["D&C",84,8,"And Caleb received it under the hand of Elihu;"],["D&C",84,9,"And Elihu under the hand of Jeremy;"],["D&C",84,10,"And Jeremy under the hand of Gad;"],["D&C",84,11,"And Gad under the hand of Esaias;"],["D&C",84,12,"And Esaias received it under the hand of God."],["D&C",84,13,"Esaias also lived in the days of Abraham, and was blessed of him—"],["D&C",84,14,"Which Abraham received the priesthood from Melchizedek, who received it through the lineage of his fathers, even till Noah;"],["D&C",84,15,"And from Noah till Enoch, through the lineage of their fathers;"],["D&C",84,16,"And from Enoch to Abel, who was slain by the conspiracy of his brother, who received the priesthood by the commandments of God, by the hand of his father Adam, who was the first man—"],["D&C",84,17,"Which priesthood continueth in the church of God in all generations, and is without beginning of days or end of years."],["D&C",84,18,"And the Lord confirmed a priesthood also upon Aaron and his seed, throughout all their generations, which priesthood also continueth and abideth forever with the priesthood which is after the holiest order of God."],["D&C",84,19,"And this greater priesthood administereth the gospel and holdeth the key of the mysteries of the kingdom, even the key of the knowledge of God."],["D&C",84,20,"Therefore, in the ordinances thereof, the power of godliness is manifest."],["D&C",84,21,"And without the ordinances thereof, and the authority of the priesthood, the power of godliness is not manifest unto men in the flesh;"],["D&C",84,22,"For without this no man can see the face of God, even the Father, and live."],["D&C",84,23,"Now this Moses plainly taught to the children of Israel in the wilderness, and sought diligently to sanctify his people that they might behold the face of God;"],["D&C",84,24,"But they hardened their hearts and could not endure his presence; therefore, the Lord in his wrath, for his anger was kindled against them, swore that they should not enter into his rest while in the wilderness, which rest is the fulness of his glory."],["D&C",84,25,"Therefore, he took Moses out of their midst, and the Holy Priesthood also;"],["D&C",84,26,"And the lesser priesthood continued, which priesthood holdeth the key of the ministering of angels and the preparatory gospel;"],["D&C",84,27,"Which gospel is the gospel of repentance and of baptism, and the remission of sins, and the law of carnal commandments, which the Lord in his wrath caused to continue with the house of Aaron among the children of Israel until John, whom God raised up, being filled with the Holy Ghost from his mother's womb."],["D&C",84,28,"For he was baptized while he was yet in his childhood, and was ordained by the angel of God at the time he was eight days old unto this power, to overthrow the kingdom of the Jews, and to make straight the way of the Lord before the face of his people, to prepare them for the coming of the Lord, in whose hand is given all power."],["D&C",84,29,"And again, the offices of elder and bishop are necessary appendages belonging unto the high priesthood."],["D&C",84,30,"And again, the offices of teacher and deacon are necessary appendages belonging to the lesser priesthood, which priesthood was confirmed upon Aaron and his sons."],["D&C",84,31,"Therefore, as I said concerning the sons of Moses—for the sons of Moses and also the sons of Aaron shall offer an acceptable offering and sacrifice in the house of the Lord, which house shall be built unto the Lord in this generation, upon the consecrated spot as I have appointed—"],["D&C",84,32,"And the sons of Moses and of Aaron shall be filled with the glory of the Lord, upon Mount Zion in the Lord's house, whose sons are ye; and also many whom I have called and sent forth to build up my church."],["D&C",84,33,"For whoso is faithful unto the obtaining these two priesthoods of which I have spoken, and the magnifying their calling, are sanctified by the Spirit unto the renewing of their bodies."],["D&C",84,34,"They become the sons of Moses and of Aaron and the seed of Abraham, and the church and kingdom, and the elect of God."],["D&C",84,35,"And also all they who receive this priesthood receive me, saith the Lord;"],["D&C",84,36,"For he that receiveth my servants receiveth me;"],["D&C",84,37,"And he that receiveth me receiveth my Father;"],["D&C",84,38,"And he that receiveth my Father receiveth my Father's kingdom; therefore all that my Father hath shall be given unto him."],["D&C",84,39,"And this is according to the oath and covenant which belongeth to the priesthood."],["D&C",84,40,"Therefore, all those who receive the priesthood, receive this oath and covenant of my Father, which he cannot break, neither can it be moved."],["D&C",84,41,"But whoso breaketh this covenant after he hath received it, and altogether turneth therefrom, shall not have forgiveness of sins in this world nor in the world to come."],["D&C",84,42,"And wo unto all those who come not unto this priesthood which ye have received, which I now confirm upon you who are present this day, by mine own voice out of the heavens; and even I have given the heavenly hosts and mine angels charge concerning you."],["D&C",84,43,"And I now give unto you a commandment to beware concerning yourselves, to give diligent heed to the words of eternal life."],["D&C",84,44,"For you shall live by every word that proceedeth forth from the mouth of God."],["D&C",84,45,"For the word of the Lord is truth, and whatsoever is truth is light, and whatsoever is light is Spirit, even the Spirit of Jesus Christ."],["D&C",84,46,"And the Spirit giveth light to every man that cometh into the world; and the Spirit enlighteneth every man through the world, that hearkeneth to the voice of the Spirit."],["D&C",84,47,"And every one that hearkeneth to the voice of the Spirit cometh unto God, even the Father."],["D&C",84,48,"And the Father teacheth him of the covenant which he has renewed and confirmed upon you, which is confirmed upon you for your sakes, and not for your sakes only, but for the sake of the whole world."],["D&C",84,49,"And the whole world lieth in sin, and groaneth under darkness and under the bondage of sin."],["D&C",84,50,"And by this you may know they are under the bondage of sin, because they come not unto me."],["D&C",84,51,"For whoso cometh not unto me is under the bondage of sin."],["D&C",84,52,"And whoso receiveth not my voice is not acquainted with my voice, and is not of me."],["D&C",84,53,"And by this you may know the righteous from the wicked, and that the whole world groaneth under sin and darkness even now."],["D&C",84,54,"And your minds in times past have been darkened because of unbelief, and because you have treated lightly the things you have received—"],["D&C",84,55,"Which vanity and unbelief have brought the whole church under condemnation."],["D&C",84,56,"And this condemnation resteth upon the children of Zion, even all."],["D&C",84,57,"And they shall remain under this condemnation until they repent and remember the new covenant, even the Book of Mormon and the former commandments which I have given them, not only to say, but to do according to that which I have written—"],["D&C",84,58,"That they may bring forth fruit meet for their Father's kingdom; otherwise there remaineth a scourge and judgment to be poured out upon the children of Zion."],["D&C",84,59,"For shall the children of the kingdom pollute my holy land? Verily, I say unto you, Nay."],["D&C",84,60,"Verily, verily, I say unto you who now hear my words, which are my voice, blessed are ye inasmuch as you receive these things;"],["D&C",84,61,"For I will forgive you of your sins with this commandment—that you remain steadfast in your minds in solemnity and the spirit of prayer, in bearing testimony to all the world of those things which are communicated unto you."],["D&C",84,62,"Therefore, go ye into all the world; and unto whatsoever place ye cannot go ye shall send, that the testimony may go from you into all the world unto every creature."],["D&C",84,63,"And as I said unto mine apostles, even so I say unto you, for you are mine apostles, even God's high priests; ye are they whom my Father hath given me; ye are my friends;"],["D&C",84,64,"Therefore, as I said unto mine apostles I say unto you again, that every soul who believeth on your words, and is baptized by water for the remission of sins, shall receive the Holy Ghost."],["D&C",84,65,"And these signs shall follow them that believe—"],["D&C",84,66,"In my name they shall do many wonderful works;"],["D&C",84,67,"In my name they shall cast out devils;"],["D&C",84,68,"In my name they shall heal the sick;"],["D&C",84,69,"In my name they shall open the eyes of the blind, and unstop the ears of the deaf;"],["D&C",84,70,"And the tongue of the dumb shall speak;"],["D&C",84,71,"And if any man shall administer poison unto them it shall not hurt them;"],["D&C",84,72,"And the poison of a serpent shall not have power to harm them."],["D&C",84,73,"But a commandment I give unto them, that they shall not boast themselves of these things, neither speak them before the world; for these things are given unto you for your profit and for salvation."],["D&C",84,74,"Verily, verily, I say unto you, they who believe not on your words, and are not baptized in water in my name, for the remission of their sins, that they may receive the Holy Ghost, shall be damned, and shall not come into my Father's kingdom where my Father and I am."],["D&C",84,75,"And this revelation unto you, and commandment, is in force from this very hour upon all the world, and the gospel is unto all who have not received it."],["D&C",84,76,"But, verily I say unto all those to whom the kingdom has been given—from you it must be preached unto them, that they shall repent of their former evil works; for they are to be upbraided for their evil hearts of unbelief, and your brethren in Zion for their rebellion against you at the time I sent you."],["D&C",84,77,"And again I say unto you, my friends, for from henceforth I shall call you friends, it is expedient that I give unto you this commandment, that ye become even as my friends in days when I was with them, traveling to preach the gospel in my power;"],["D&C",84,78,"For I suffered them not to have purse or scrip, neither two coats."],["D&C",84,79,"Behold, I send you out to prove the world, and the laborer is worthy of his hire."],["D&C",84,80,"And any man that shall go and preach this gospel of the kingdom, and fail not to continue faithful in all things, shall not be weary in mind, neither darkened, neither in body, limb, nor joint; and a hair of his head shall not fall to the ground unnoticed. And they shall not go hungry, neither athirst."],["D&C",84,81,"Therefore, take ye no thought for the morrow, for what ye shall eat, or what ye shall drink, or wherewithal ye shall be clothed."],["D&C",84,82,"For, consider the lilies of the field, how they grow, they toil not, neither do they spin; and the kingdoms of the world, in all their glory, are not arrayed like one of these."],["D&C",84,83,"For your Father, who is in heaven, knoweth that you have need of all these things."],["D&C",84,84,"Therefore, let the morrow take thought for the things of itself."],["D&C",84,85,"Neither take ye thought beforehand what ye shall say; but treasure up in your minds continually the words of life, and it shall be given you in the very hour that portion that shall be meted unto every man."],["D&C",84,86,"Therefore, let no man among you, for this commandment is unto all the faithful who are called of God in the church unto the ministry, from this hour take purse or scrip, that goeth forth to proclaim this gospel of the kingdom."],["D&C",84,87,"Behold, I send you out to reprove the world of all their unrighteous deeds, and to teach them of a judgment which is to come."],["D&C",84,88,"And whoso receiveth you, there I will be also, for I will go before your face. I will be on your right hand and on your left, and my Spirit shall be in your hearts, and mine angels round about you, to bear you up."],["D&C",84,89,"Whoso receiveth you receiveth me; and the same will feed you, and clothe you, and give you money."],["D&C",84,90,"And he who feeds you, or clothes you, or gives you money, shall in nowise lose his reward."],["D&C",84,91,"And he that doeth not these things is not my disciple; by this you may know my disciples."],["D&C",84,92,"He that receiveth you not, go away from him alone by yourselves, and cleanse your feet even with water, pure water, whether in heat or in cold, and bear testimony of it unto your Father which is in heaven, and return not again unto that man."],["D&C",84,93,"And in whatsoever village or city ye enter, do likewise."],["D&C",84,94,"Nevertheless, search diligently and spare not; and wo unto that house, or that village or city that rejecteth you, or your words, or your testimony concerning me."],["D&C",84,95,"Wo, I say again, unto that house, or that village or city that rejecteth you, or your words, or your testimony of me;"],["D&C",84,96,"For I, the Almighty, have laid my hands upon the nations, to scourge them for their wickedness."],["D&C",84,97,"And plagues shall go forth, and they shall not be taken from the earth until I have completed my work, which shall be cut short in righteousness—"],["D&C",84,98,"Until all shall know me, who remain, even from the least unto the greatest, and shall be filled with the knowledge of the Lord, and shall see eye to eye, and shall lift up their voice, and with the voice together sing this new song, saying:"],["D&C",84,99,"The Lord hath brought again Zion;"],["D&C",84,100,"The Lord hath redeemed his people;"],["D&C",84,101,"The earth hath travailed and brought forth her strength;"],["D&C",84,102,"Glory, and honor, and power, and might,"],["D&C",84,103,"And again, verily, verily, I say unto you, it is expedient that every man who goes forth to proclaim mine everlasting gospel, that inasmuch as they have families, and receive money by gift, that they should send it unto them or make use of it for their benefit, as the Lord shall direct them, for thus it seemeth me good."],["D&C",84,104,"And let all those who have not families, who receive money, send it up unto the bishop in Zion, or unto the bishop in Ohio, that it may be consecrated for the bringing forth of the revelations and the printing thereof, and for establishing Zion."],["D&C",84,105,"And if any man shall give unto any of you a coat, or a suit, take the old and cast it unto the poor, and go on your way rejoicing."],["D&C",84,106,"And if any man among you be strong in the Spirit, let him take with him him that is weak, that he may be edified in all meekness, that he may become strong also."],["D&C",84,107,"Therefore, take with you those who are ordained unto the lesser priesthood, and send them before you to make appointments, and to prepare the way, and to fill appointments that you yourselves are not able to fill."],["D&C",84,108,"Behold, this is the way that mine apostles, in ancient days, built up my church unto me."],["D&C",84,109,"Therefore, let every man stand in his own office, and labor in his own calling; and let not the head say unto the feet it hath no need of the feet; for without the feet how shall the body be able to stand?"],["D&C",84,110,"Also the body hath need of every member, that all may be edified together, that the system may be kept perfect."],["D&C",84,111,"And behold, the high priests should travel, and also the elders, and also the lesser priests; but the deacons and teachers should be appointed to watch over the church, to be standing ministers unto the church."],["D&C",84,112,"And the bishop, Newel K. Whitney, also should travel round about and among all the churches, searching after the poor to administer to their wants by humbling the rich and the proud."],["D&C",84,113,"He should also employ an agent to take charge and to do his secular business as he shall direct."],["D&C",84,114,"Nevertheless, let the bishop go unto the city of New York, also to the city of Albany, and also to the city of Boston, and warn the people of those cities with the sound of the gospel, with a loud voice, of the desolation and utter abolishment which await them if they do reject these things."],["D&C",84,115,"For if they do reject these things the hour of their judgment is nigh, and their house shall be left unto them desolate."],["D&C",84,116,"Let him trust in me and he shall not be confounded; and a hair of his head shall not fall to the ground unnoticed."],["D&C",84,117,"And verily I say unto you, the rest of my servants, go ye forth as your circumstances shall permit, in your several callings, unto the great and notable cities and villages, reproving the world in righteousness of all their unrighteous and ungodly deeds, setting forth clearly and understandingly the desolation of abomination in the last days."],["D&C",84,118,"For, with you saith the Lord Almighty, I will rend their kingdoms; I will not only shake the earth, but the starry heavens shall tremble."],["D&C",84,119,"For I, the Lord, have put forth my hand to exert the powers of heaven; ye cannot see it now, yet a little while and ye shall see it, and know that I am, and that I will come and reign with my people."],["D&C",84,120,"I am Alpha and Omega, the beginning and the end. Amen."],["D&C",85,1,"It is the duty of the Lord's clerk, whom he has appointed, to keep a history, and a general church record of all things that transpire in Zion, and of all those who consecrate properties, and receive inheritances legally from the bishop;"],["D&C",85,2,"And also their manner of life, their faith, and works; and also of the apostates who apostatize after receiving their inheritances."],["D&C",85,3,"It is contrary to the will and commandment of God that those who receive not their inheritance by consecration, agreeable to his law, which he has given, that he may tithe his people, to prepare them against the day of vengeance and burning, should have their names enrolled with the people of God."],["D&C",85,4,"Neither is their genealogy to be kept, or to be had where it may be found on any of the records or history of the church."],["D&C",85,5,"Their names shall not be found, neither the names of the fathers, nor the names of the children written in the book of the law of God, saith the Lord of Hosts."],["D&C",85,6,"Yea, thus saith the still small voice, which whispereth through and pierceth all things, and often times it maketh my bones to quake while it maketh manifest, saying:"],["D&C",85,7,"And it shall come to pass that I, the Lord God, will send one mighty and strong, holding the scepter of power in his hand, clothed with light for a covering, whose mouth shall utter words, eternal words; while his bowels shall be a fountain of truth, to set in order the house of God, and to arrange by lot the inheritances of the saints whose names are found, and the names of their fathers, and of their children, enrolled in the book of the law of God;"],["D&C",85,8,"While that man, who was called of God and appointed, that putteth forth his hand to steady the ark of God, shall fall by the shaft of death, like as a tree that is smitten by the vivid shaft of lightning."],["D&C",85,9,"And all they who are not found written in the book of remembrance shall find none inheritance in that day, but they shall be cut asunder, and their portion shall be appointed them among unbelievers, where are wailing and gnashing of teeth."],["D&C",85,10,"These things I say not of myself; therefore, as the Lord speaketh, he will also fulfil."],["D&C",85,11,"And they who are of the High Priesthood, whose names are not found written in the book of the law, or that are found to have apostatized, or to have been cut off from the church, as well as the lesser priesthood, or the members, in that day shall not find an inheritance among the saints of the Most High;"],["D&C",85,12,"Therefore, it shall be done unto them as unto the children of the priest, as will be found recorded in the second chapter and sixty-first and second verses of Ezra."],["D&C",86,1,"Verily, thus saith the Lord unto you my servants, concerning the parable of the wheat and of the tares:"],["D&C",86,2,"Behold, verily I say, the field was the world, and the apostles were the sowers of the seed;"],["D&C",86,3,"And after they have fallen asleep the great persecutor of the church, the apostate, the whore, even Babylon, that maketh all nations to drink of her cup, in whose hearts the enemy, even Satan, sitteth to reign—behold he soweth the tares; wherefore, the tares choke the wheat and drive the church into the wilderness."],["D&C",86,4,"But behold, in the last days, even now while the Lord is beginning to bring forth the word, and the blade is springing up and is yet tender—"],["D&C",86,5,"Behold, verily I say unto you, the angels are crying unto the Lord day and night, who are ready and waiting to be sent forth to reap down the fields;"],["D&C",86,6,"But the Lord saith unto them, pluck not up the tares while the blade is yet tender (for verily your faith is weak), lest you destroy the wheat also."],["D&C",86,7,"Therefore, let the wheat and the tares grow together until the harvest is fully ripe; then ye shall first gather out the wheat from among the tares, and after the gathering of the wheat, behold and lo, the tares are bound in bundles, and the field remaineth to be burned."],["D&C",86,8,"Therefore, thus saith the Lord unto you, with whom the priesthood hath continued through the lineage of your fathers—"],["D&C",86,9,"For ye are lawful heirs, according to the flesh, and have been hid from the world with Christ in God—"],["D&C",86,10,"Therefore your life and the priesthood have remained, and must needs remain through you and your lineage until the restoration of all things spoken by the mouths of all the holy prophets since the world began."],["D&C",86,11,"Therefore, blessed are ye if ye continue in my goodness, a light unto the Gentiles, and through this priesthood, a savior unto my people Israel. The Lord hath said it. Amen."],["D&C",87,1,"Verily, thus saith the Lord concerning the wars that will shortly come to pass, beginning at the rebellion of South Carolina, which will eventually terminate in the death and misery of many souls;"],["D&C",87,2,"And the time will come that war will be poured out upon all nations, beginning at this place."],["D&C",87,3,"For behold, the Southern States shall be divided against the Northern States, and the Southern States will call on other nations, even the nation of Great Britain, as it is called, and they shall also call upon other nations, in order to defend themselves against other nations; and then war shall be poured out upon all nations."],["D&C",87,4,"And it shall come to pass, after many days, slaves shall rise up against their masters, who shall be marshaled and disciplined for war."],["D&C",87,5,"And it shall come to pass also that the remnants who are left of the land will marshal themselves, and shall become exceedingly angry, and shall vex the Gentiles with a sore vexation."],["D&C",87,6,"And thus, with the sword and by bloodshed the inhabitants of the earth shall mourn; and with famine, and plague, and earthquake, and the thunder of heaven, and the fierce and vivid lightning also, shall the inhabitants of the earth be made to feel the wrath, and indignation, and chastening hand of an Almighty God, until the consumption decreed hath made a full end of all nations;"],["D&C",87,7,"That the cry of the saints, and of the blood of the saints, shall cease to come up into the ears of the Lord of Sabaoth, from the earth, to be avenged of their enemies."],["D&C",87,8,"Wherefore, stand ye in holy places, and be not moved, until the day of the Lord come; for behold, it cometh quickly, saith the Lord. Amen."],["D&C",88,1,"Verily, thus saith the Lord unto you who have assembled yourselves together to receive his will concerning you:"],["D&C",88,2,"Behold, this is pleasing unto your Lord, and the angels rejoice over you; the alms of your prayers have come up into the ears of the Lord of Sabaoth, and are recorded in the book of the names of the sanctified, even them of the celestial world."],["D&C",88,3,"Wherefore, I now send upon you another Comforter, even upon you my friends, that it may abide in your hearts, even the Holy Spirit of promise; which other Comforter is the same that I promised unto my disciples, as is recorded in the testimony of John."],["D&C",88,4,"This Comforter is the promise which I give unto you of eternal life, even the glory of the celestial kingdom;"],["D&C",88,5,"Which glory is that of the church of the Firstborn, even of God, the holiest of all, through Jesus Christ his Son—"],["D&C",88,6,"He that ascended up on high, as also he descended below all things, in that he comprehended all things, that he might be in all and through all things, the light of truth;"],["D&C",88,7,"Which truth shineth. This is the light of Christ. As also he is in the sun, and the light of the sun, and the power thereof by which it was made."],["D&C",88,8,"As also he is in the moon, and is the light of the moon, and the power thereof by which it was made;"],["D&C",88,9,"As also the light of the stars, and the power thereof by which they were made;"],["D&C",88,10,"And the earth also, and the power thereof, even the earth upon which you stand."],["D&C",88,11,"And the light which shineth, which giveth you light, is through him who enlighteneth your eyes, which is the same light that quickeneth your understandings;"],["D&C",88,12,"Which light proceedeth forth from the presence of God to fill the immensity of space—"],["D&C",88,13,"The light which is in all things, which giveth life to all things, which is the law by which all things are governed, even the power of God who sitteth upon his throne, who is in the bosom of eternity, who is in the midst of all things."],["D&C",88,14,"Now, verily I say unto you, that through the redemption which is made for you is brought to pass the resurrection from the dead."],["D&C",88,15,"And the spirit and the body are the soul of man."],["D&C",88,16,"And the resurrection from the dead is the redemption of the soul."],["D&C",88,17,"And the redemption of the soul is through him that quickeneth all things, in whose bosom it is decreed that the poor and the meek of the earth shall inherit it."],["D&C",88,18,"Therefore, it must needs be sanctified from all unrighteousness, that it may be prepared for the celestial glory;"],["D&C",88,19,"For after it hath filled the measure of its creation, it shall be crowned with glory, even with the presence of God the Father;"],["D&C",88,20,"That bodies who are of the celestial kingdom may possess it forever and ever; for, for this intent was it made and created, and for this intent are they sanctified."],["D&C",88,21,"And they who are not sanctified through the law which I have given unto you, even the law of Christ, must inherit another kingdom, even that of a terrestrial kingdom, or that of a telestial kingdom."],["D&C",88,22,"For he who is not able to abide the law of a celestial kingdom cannot abide a celestial glory."],["D&C",88,23,"And he who cannot abide the law of a terrestrial kingdom cannot abide a terrestrial glory."],["D&C",88,24,"And he who cannot abide the law of a telestial kingdom cannot abide a telestial glory; therefore he is not meet for a kingdom of glory. Therefore he must abide a kingdom which is not a kingdom of glory."],["D&C",88,25,"And again, verily I say unto you, the earth abideth the law of a celestial kingdom, for it filleth the measure of its creation, and transgresseth not the law—"],["D&C",88,26,"Wherefore, it shall be sanctified; yea, notwithstanding it shall die, it shall be quickened again, and shall abide the power by which it is quickened, and the righteous shall inherit it."],["D&C",88,27,"For notwithstanding they die, they also shall rise again, a spiritual body."],["D&C",88,28,"They who are of a celestial spirit shall receive the same body which was a natural body; even ye shall receive your bodies, and your glory shall be that glory by which your bodies are quickened."],["D&C",88,29,"Ye who are quickened by a portion of the celestial glory shall then receive of the same, even a fulness."],["D&C",88,30,"And they who are quickened by a portion of the terrestrial glory shall then receive of the same, even a fulness."],["D&C",88,31,"And also they who are quickened by a portion of the telestial glory shall then receive of the same, even a fulness."],["D&C",88,32,"And they who remain shall also be quickened; nevertheless, they shall return again to their own place, to enjoy that which they are willing to receive, because they were not willing to enjoy that which they might have received."],["D&C",88,33,"For what doth it profit a man if a gift is bestowed upon him, and he receive not the gift? Behold, he rejoices not in that which is given unto him, neither rejoices in him who is the giver of the gift."],["D&C",88,34,"And again, verily I say unto you, that which is governed by law is also preserved by law and perfected and sanctified by the same."],["D&C",88,35,"That which breaketh a law, and abideth not by law, but seeketh to become a law unto itself, and willeth to abide in sin, and altogether abideth in sin, cannot be sanctified by law, neither by mercy, justice, nor judgment. Therefore, they must remain filthy still."],["D&C",88,36,"All kingdoms have a law given;"],["D&C",88,37,"And there are many kingdoms; for there is no space in the which there is no kingdom; and there is no kingdom in which there is no space, either a greater or a lesser kingdom."],["D&C",88,38,"And unto every kingdom is given a law; and unto every law there are certain bounds also and conditions."],["D&C",88,39,"All beings who abide not in those conditions are not justified."],["D&C",88,40,"For intelligence cleaveth unto intelligence; wisdom receiveth wisdom; truth embraceth truth; virtue loveth virtue; light cleaveth unto light; mercy hath compassion on mercy and claimeth her own; justice continueth its course and claimeth its own; judgment goeth before the face of him who sitteth upon the throne and governeth and executeth all things."],["D&C",88,41,"He comprehendeth all things, and all things are before him, and all things are round about him; and he is above all things, and in all things, and is through all things, and is round about all things; and all things are by him, and of him, even God, forever and ever."],["D&C",88,42,"And again, verily I say unto you, he hath given a law unto all things, by which they move in their times and their seasons;"],["D&C",88,43,"And their courses are fixed, even the courses of the heavens and the earth, which comprehend the earth and all the planets."],["D&C",88,44,"And they give light to each other in their times and in their seasons, in their minutes, in their hours, in their days, in their weeks, in their months, in their years—all these are one year with God, but not with man."],["D&C",88,45,"The earth rolls upon her wings, and the sun giveth his light by day, and the moon giveth her light by night, and the stars also give their light, as they roll upon their wings in their glory, in the midst of the power of God."],["D&C",88,46,"Unto what shall I liken these kingdoms, that ye may understand?"],["D&C",88,47,"Behold, all these are kingdoms, and any man who hath seen any or the least of these hath seen God moving in his majesty and power."],["D&C",88,48,"I say unto you, he hath seen him; nevertheless, he who came unto his own was not comprehended."],["D&C",88,49,"The light shineth in darkness, and the darkness comprehendeth it not; nevertheless, the day shall come when you shall comprehend even God, being quickened in him and by him."],["D&C",88,50,"Then shall ye know that ye have seen me, that I am, and that I am the true light that is in you, and that you are in me; otherwise ye could not abound."],["D&C",88,51,"Behold, I will liken these kingdoms unto a man having a field, and he sent forth his servants into the field to dig in the field."],["D&C",88,52,"And he said unto the first: Go ye and labor in the field, and in the first hour I will come unto you, and ye shall behold the joy of my countenance."],["D&C",88,53,"And he said unto the second: Go ye also into the field, and in the second hour I will visit you with the joy of my countenance."],["D&C",88,54,"And also unto the third, saying: I will visit you;"],["D&C",88,55,"And unto the fourth, and so on unto the twelfth."],["D&C",88,56,"And the lord of the field went unto the first in the first hour, and tarried with him all that hour, and he was made glad with the light of the countenance of his lord."],["D&C",88,57,"And then he withdrew from the first that he might visit the second also, and the third, and the fourth, and so on unto the twelfth."],["D&C",88,58,"And thus they all received the light of the countenance of their lord, every man in his hour, and in his time, and in his season—"],["D&C",88,59,"Beginning at the first, and so on unto the last, and from the last unto the first, and from the first unto the last;"],["D&C",88,60,"Every man in his own order, until his hour was finished, even according as his lord had commanded him, that his lord might be glorified in him, and he in his lord, that they all might be glorified."],["D&C",88,61,"Therefore, unto this parable I will liken all these kingdoms, and the inhabitants thereof—every kingdom in its hour, and in its time, and in its season, even according to the decree which God hath made."],["D&C",88,62,"And again, verily I say unto you, my friends, I leave these sayings with you to ponder in your hearts, with this commandment which I give unto you, that ye shall call upon me while I am near—"],["D&C",88,63,"Draw near unto me and I will draw near unto you; seek me diligently and ye shall find me; ask, and ye shall receive; knock, and it shall be opened unto you."],["D&C",88,64,"Whatsoever ye ask the Father in my name it shall be given unto you, that is expedient for you;"],["D&C",88,65,"And if ye ask anything that is not expedient for you, it shall turn unto your condemnation."],["D&C",88,66,"Behold, that which you hear is as the voice of one crying in the wilderness—in the wilderness, because you cannot see him—my voice, because my voice is Spirit; my Spirit is truth; truth abideth and hath no end; and if it be in you it shall abound."],["D&C",88,67,"And if your eye be single to my glory, your whole bodies shall be filled with light, and there shall be no darkness in you; and that body which is filled with light comprehendeth all things."],["D&C",88,68,"Therefore, sanctify yourselves that your minds become single to God, and the days will come that you shall see him; for he will unveil his face unto you, and it shall be in his own time, and in his own way, and according to his own will."],["D&C",88,69,"Remember the great and last promise which I have made unto you; cast away your idle thoughts and your excess of laughter far from you."],["D&C",88,70,"Tarry ye, tarry ye in this place, and call a solemn assembly, even of those who are the first laborers in this last kingdom."],["D&C",88,71,"And let those whom they have warned in their traveling call on the Lord, and ponder the warning in their hearts which they have received, for a little season."],["D&C",88,72,"Behold, and lo, I will take care of your flocks, and will raise up elders and send unto them."],["D&C",88,73,"Behold, I will hasten my work in its time."],["D&C",88,74,"And I give unto you, who are the first laborers in this last kingdom, a commandment that you assemble yourselves together, and organize yourselves, and prepare yourselves, and sanctify yourselves; yea, purify your hearts, and cleanse your hands and your feet before me, that I may make you clean;"],["D&C",88,75,"That I may testify unto your Father, and your God, and my God, that you are clean from the blood of this wicked generation; that I may fulfil this promise, this great and last promise, which I have made unto you, when I will."],["D&C",88,76,"Also, I give unto you a commandment that ye shall continue in prayer and fasting from this time forth."],["D&C",88,77,"And I give unto you a commandment that you shall teach one another the doctrine of the kingdom."],["D&C",88,78,"Teach ye diligently and my grace shall attend you, that you may be instructed more perfectly in theory, in principle, in doctrine, in the law of the gospel, in all things that pertain unto the kingdom of God, that are expedient for you to understand;"],["D&C",88,79,"Of things both in heaven and in the earth, and under the earth; things which have been, things which are, things which must shortly come to pass; things which are at home, things which are abroad; the wars and the perplexities of the nations, and the judgments which are on the land; and a knowledge also of countries and of kingdoms—"],["D&C",88,80,"That ye may be prepared in all things when I shall send you again to magnify the calling whereunto I have called you, and the mission with which I have commissioned you."],["D&C",88,81,"Behold, I sent you out to testify and warn the people, and it becometh every man who hath been warned to warn his neighbor."],["D&C",88,82,"Therefore, they are left without excuse, and their sins are upon their own heads."],["D&C",88,83,"He that seeketh me early shall find me, and shall not be forsaken."],["D&C",88,84,"Therefore, tarry ye, and labor diligently, that you may be perfected in your ministry to go forth among the Gentiles for the last time, as many as the mouth of the Lord shall name, to bind up the law and seal up the testimony, and to prepare the saints for the hour of judgment which is to come;"],["D&C",88,85,"That their souls may escape the wrath of God, the desolation of abomination which awaits the wicked, both in this world and in the world to come. Verily, I say unto you, let those who are not the first elders continue in the vineyard until the mouth of the Lord shall call them, for their time is not yet come; their garments are not clean from the blood of this generation."],["D&C",88,86,"Abide ye in the liberty wherewith ye are made free; entangle not yourselves in sin, but let your hands be clean, until the Lord comes."],["D&C",88,87,"For not many days hence and the earth shall tremble and reel to and fro as a drunken man; and the sun shall hide his face, and shall refuse to give light; and the moon shall be bathed in blood; and the stars shall become exceedingly angry, and shall cast themselves down as a fig that falleth from off a fig tree."],["D&C",88,88,"And after your testimony cometh wrath and indignation upon the people."],["D&C",88,89,"For after your testimony cometh the testimony of earthquakes, that shall cause groanings in the midst of her, and men shall fall upon the ground and shall not be able to stand."],["D&C",88,90,"And also cometh the testimony of the voice of thunderings, and the voice of lightnings, and the voice of tempests, and the voice of the waves of the sea heaving themselves beyond their bounds."],["D&C",88,91,"And all things shall be in commotion; and surely, men's hearts shall fail them; for fear shall come upon all people."],["D&C",88,92,"And angels shall fly through the midst of heaven, crying with a loud voice, sounding the trump of God, saying: Prepare ye, prepare ye, O inhabitants of the earth; for the judgment of our God is come. Behold, and lo, the Bridegroom cometh; go ye out to meet him."],["D&C",88,93,"And immediately there shall appear a great sign in heaven, and all people shall see it together."],["D&C",88,94,"And another angel shall sound his trump, saying: That great church, the mother of abominations, that made all nations drink of the wine of the wrath of her fornication, that persecuteth the saints of God, that shed their blood—she who sitteth upon many waters, and upon the islands of the sea—behold, she is the tares of the earth; she is bound in bundles; her bands are made strong, no man can loose them; therefore, she is ready to be burned. And he shall sound his trump both long and loud, and all nations shall hear it."],["D&C",88,95,"And there shall be silence in heaven for the space of half an hour; and immediately after shall the curtain of heaven be unfolded, as a scroll is unfolded after it is rolled up, and the face of the Lord shall be unveiled;"],["D&C",88,96,"And the saints that are upon the earth, who are alive, shall be quickened and be caught up to meet him."],["D&C",88,97,"And they who have slept in their graves shall come forth, for their graves shall be opened; and they also shall be caught up to meet him in the midst of the pillar of heaven—"],["D&C",88,98,"They are Christ's, the first fruits, they who shall descend with him first, and they who are on the earth and in their graves, who are first caught up to meet him; and all this by the voice of the sounding of the trump of the angel of God."],["D&C",88,99,"And after this another angel shall sound, which is the second trump; and then cometh the redemption of those who are Christ's at his coming; who have received their part in that prison which is prepared for them, that they might receive the gospel, and be judged according to men in the flesh."],["D&C",88,100,"And again, another trump shall sound, which is the third trump; and then come the spirits of men who are to be judged, and are found under condemnation;"],["D&C",88,101,"And these are the rest of the dead; and they live not again until the thousand years are ended, neither again, until the end of the earth."],["D&C",88,102,"And another trump shall sound, which is the fourth trump, saying: There are found among those who are to remain until that great and last day, even the end, who shall remain filthy still."],["D&C",88,103,"And another trump shall sound, which is the fifth trump, which is the fifth angel who committeth the everlasting gospel—flying through the midst of heaven, unto all nations, kindreds, tongues, and people;"],["D&C",88,104,"And this shall be the sound of his trump, saying to all people, both in heaven and in earth, and that are under the earth—for every ear shall hear it, and every knee shall bow, and every tongue shall confess, while they hear the sound of the trump, saying: Fear God, and give glory to him who sitteth upon the throne, forever and ever; for the hour of his judgment is come."],["D&C",88,105,"And again, another angel shall sound his trump, which is the sixth angel, saying: She is fallen who made all nations drink of the wine of the wrath of her fornication; she is fallen, is fallen!"],["D&C",88,106,"And again, another angel shall sound his trump, which is the seventh angel, saying: It is finished; it is finished! The Lamb of God hath overcome and trodden the wine-press alone, even the wine-press of the fierceness of the wrath of Almighty God."],["D&C",88,107,"And then shall the angels be crowned with the glory of his might, and the saints shall be filled with his glory, and receive their inheritance and be made equal with him."],["D&C",88,108,"And then shall the first angel again sound his trump in the ears of all living, and reveal the secret acts of men, and the mighty works of God in the first thousand years."],["D&C",88,109,"And then shall the second angel sound his trump, and reveal the secret acts of men, and the thoughts and intents of their hearts, and the mighty works of God in the second thousand years—"],["D&C",88,110,"And so on, until the seventh angel shall sound his trump; and he shall stand forth upon the land and upon the sea, and swear in the name of him who sitteth upon the throne, that there shall be time no longer; and Satan shall be bound, that old serpent, who is called the devil, and shall not be loosed for the space of a thousand years."],["D&C",88,111,"And then he shall be loosed for a little season, that he may gather together his armies."],["D&C",88,112,"And Michael, the seventh angel, even the archangel, shall gather together his armies, even the hosts of heaven."],["D&C",88,113,"And the devil shall gather together his armies; even the hosts of hell, and shall come up to battle against Michael and his armies."],["D&C",88,114,"And then cometh the battle of the great God; and the devil and his armies shall be cast away into their own place, that they shall not have power over the saints any more at all."],["D&C",88,115,"For Michael shall fight their battles, and shall overcome him who seeketh the throne of him who sitteth upon the throne, even the Lamb."],["D&C",88,116,"This is the glory of God, and the sanctified; and they shall not any more see death."],["D&C",88,117,"Therefore, verily I say unto you, my friends, call your solemn assembly, as I have commanded you."],["D&C",88,118,"And as all have not faith, seek ye diligently and teach one another words of wisdom; yea, seek ye out of the best books words of wisdom; seek learning, even by study and also by faith."],["D&C",88,119,"Organize yourselves; prepare every needful thing; and establish a house, even a house of prayer, a house of fasting, a house of faith, a house of learning, a house of glory, a house of order, a house of God;"],["D&C",88,120,"That your incomings may be in the name of the Lord; that your outgoings may be in the name of the Lord; that all your salutations may be in the name of the Lord, with uplifted hands unto the Most High."],["D&C",88,121,"Therefore, cease from all your light speeches, from all laughter, from all your lustful desires, from all your pride and light-mindedness, and from all your wicked doings."],["D&C",88,122,"Appoint among yourselves a teacher, and let not all be spokesmen at once; but let one speak at a time and let all listen unto his sayings, that when all have spoken that all may be edified of all, and that every man may have an equal privilege."],["D&C",88,123,"See that ye love one another; cease to be covetous; learn to impart one to another as the gospel requires."],["D&C",88,124,"Cease to be idle; cease to be unclean; cease to find fault one with another; cease to sleep longer than is needful; retire to thy bed early, that ye may not be weary; arise early, that your bodies and your minds may be invigorated."],["D&C",88,125,"And above all things, clothe yourselves with the bond of charity, as with a mantle, which is the bond of perfectness and peace."],["D&C",88,126,"Pray always, that ye may not faint, until I come. Behold, and lo, I will come quickly, and receive you unto myself. Amen."],["D&C",88,127,"And again, the order of the house prepared for the presidency of the school of the prophets, established for their instruction in all things that are expedient for them, even for all the officers of the church, or in other words, those who are called to the ministry in the church, beginning at the high priests, even down to the deacons—"],["D&C",88,128,"And this shall be the order of the house of the presidency of the school: He that is appointed to be president, or teacher, shall be found standing in his place, in the house which shall be prepared for him."],["D&C",88,129,"Therefore, he shall be first in the house of God, in a place that the congregation in the house may hear his words carefully and distinctly, not with loud speech."],["D&C",88,130,"And when he cometh into the house of God, for he should be first in the house—behold, this is beautiful, that he may be an example—"],["D&C",88,131,"Let him offer himself in prayer upon his knees before God, in token or remembrance of the everlasting covenant."],["D&C",88,132,"And when any shall come in after him, let the teacher arise, and, with uplifted hands to heaven, yea, even directly, salute his brother or brethren with these words:"],["D&C",88,133,"Art thou a brother or brethren? I salute you in the name of the Lord Jesus Christ, in token or remembrance of the everlasting covenant, in which covenant I receive you to fellowship, in a determination that is fixed, immovable, and unchangeable, to be your friend and brother through the grace of God in the bonds of love, to walk in all the commandments of God blameless, in thanksgiving, forever and ever. Amen."],["D&C",88,134,"And he that is found unworthy of this salutation shall not have place among you; for ye shall not suffer that mine house shall be polluted by him."],["D&C",88,135,"And he that cometh in and is faithful before me, and is a brother, or if they be brethren, they shall salute the president or teacher with uplifted hands to heaven, with this same prayer and covenant, or by saying Amen, in token of the same."],["D&C",88,136,"Behold, verily, I say unto you, this is an ensample unto you for a salutation to one another in the house of God, in the school of the prophets."],["D&C",88,137,"And ye are called to do this by prayer and thanksgiving, as the Spirit shall give utterance in all your doings in the house of the Lord, in the school of the prophets, that it may become a sanctuary, a tabernacle of the Holy Spirit to your edification."],["D&C",88,138,"And ye shall not receive any among you into this school save he is clean from the blood of this generation;"],["D&C",88,139,"And he shall be received by the ordinance of the washing of feet, for unto this end was the ordinance of the washing of feet instituted."],["D&C",88,140,"And again, the ordinance of washing feet is to be administered by the president, or presiding elder of the church."],["D&C",88,141,"It is to be commenced with prayer; and after partaking of bread and wine, he is to gird himself according to the pattern given in the thirteenth chapter of John's testimony concerning me. Amen."],["D&C",89,1,"A WORD OF WISDOM, for the benefit of the council of high priests, assembled in Kirtland, and the church, and also the saints in Zion—"],["D&C",89,2,"To be sent greeting; not by commandment or constraint, but by revelation and the word of wisdom, showing forth the order and will of God in the temporal salvation of all saints in the last days—"],["D&C",89,3,"Given for a principle with promise, adapted to the capacity of the weak and the weakest of all saints, who are or can be called saints."],["D&C",89,4,"Behold, verily, thus saith the Lord unto you: In consequence of evils and designs which do and will exist in the hearts of conspiring men in the last days, I have warned you, and forewarn you, by giving unto you this word of wisdom by revelation—"],["D&C",89,5,"That inasmuch as any man drinketh wine or strong drink among you, behold it is not good, neither meet in the sight of your Father, only in assembling yourselves together to offer up your sacraments before him."],["D&C",89,6,"And, behold, this should be wine, yea, pure wine of the grape of the vine, of your own make."],["D&C",89,7,"And, again, strong drinks are not for the belly, but for the washing of your bodies."],["D&C",89,8,"And again, tobacco is not for the body, neither for the belly, and is not good for man, but is an herb for bruises and all sick cattle, to be used with judgment and skill."],["D&C",89,9,"And again, hot drinks are not for the body or belly."],["D&C",89,10,"And again, verily I say unto you, all wholesome herbs God hath ordained for the constitution, nature, and use of man—"],["D&C",89,11,"Every herb in the season thereof, and every fruit in the season thereof; all these to be used with prudence and thanksgiving."],["D&C",89,12,"Yea, flesh also of beasts and of the fowls of the air, I, the Lord, have ordained for the use of man with thanksgiving; nevertheless they are to be used sparingly;"],["D&C",89,13,"And it is pleasing unto me that they should not be used, only in times of winter, or of cold, or famine."],["D&C",89,14,"All grain is ordained for the use of man and of beasts, to be the staff of life, not only for man but for the beasts of the field, and the fowls of heaven, and all wild animals that run or creep on the earth;"],["D&C",89,15,"And these hath God made for the use of man only in times of famine and excess of hunger."],["D&C",89,16,"All grain is good for the food of man; as also the fruit of the vine; that which yieldeth fruit, whether in the ground or above the ground—"],["D&C",89,17,"Nevertheless, wheat for man, and corn for the ox, and oats for the horse, and rye for the fowls and for swine, and for all beasts of the field, and barley for all useful animals, and for mild drinks, as also other grain."],["D&C",89,18,"And all saints who remember to keep and do these sayings, walking in obedience to the commandments, shall receive health in their navel and marrow to their bones;"],["D&C",89,19,"And shall find wisdom and great treasures of knowledge, even hidden treasures;"],["D&C",89,20,"And shall run and not be weary, and shall walk and not faint."],["D&C",89,21,"And I, the Lord, give unto them a promise, that the destroying angel shall pass by them, as the children of Israel, and not slay them. Amen."],["D&C",90,1,"Thus saith the Lord, verily, verily I say unto you my son, thy sins are forgiven thee, according to thy petition, for thy prayers and the prayers of thy brethren have come up into my ears."],["D&C",90,2,"Therefore, thou art blessed from henceforth that bear the keys of the kingdom given unto you; which kingdom is coming forth for the last time."],["D&C",90,3,"Verily I say unto you, the keys of this kingdom shall never be taken from you, while thou art in the world, neither in the world to come;"],["D&C",90,4,"Nevertheless, through you shall the oracles be given to another, yea, even unto the church."],["D&C",90,5,"And all they who receive the oracles of God, let them beware how they hold them lest they are accounted as a light thing, and are brought under condemnation thereby, and stumble and fall when the storms descend, and the winds blow, and the rains descend, and beat upon their house."],["D&C",90,6,"And again, verily I say unto thy brethren, Sidney Rigdon and Frederick G. Williams, their sins are forgiven them also, and they are accounted as equal with thee in holding the keys of this last kingdom;"],["D&C",90,7,"As also through your administration the keys of the school of the prophets, which I have commanded to be organized;"],["D&C",90,8,"That thereby they may be perfected in their ministry for the salvation of Zion, and of the nations of Israel, and of the Gentiles, as many as will believe;"],["D&C",90,9,"That through your administration they may receive the word, and through their administration the word may go forth unto the ends of the earth, unto the Gentiles first, and then, behold, and lo, they shall turn unto the Jews."],["D&C",90,10,"And then cometh the day when the arm of the Lord shall be revealed in power in convincing the nations, the heathen nations, the house of Joseph, of the gospel of their salvation."],["D&C",90,11,"For it shall come to pass in that day, that every man shall hear the fulness of the gospel in his own tongue, and in his own language, through those who are ordained unto this power, by the administration of the Comforter, shed forth upon them for the revelation of Jesus Christ."],["D&C",90,12,"And now, verily I say unto you, I give unto you a commandment that you continue in the ministry and presidency."],["D&C",90,13,"And when you have finished the translation of the prophets, you shall from thenceforth preside over the affairs of the church and the school;"],["D&C",90,14,"And from time to time, as shall be manifested by the Comforter, receive revelations to unfold the mysteries of the kingdom;"],["D&C",90,15,"And set in order the churches, and study and learn, and become acquainted with all good books, and with languages, tongues, and people."],["D&C",90,16,"And this shall be your business and mission in all your lives, to preside in council, and set in order all the affairs of this church and kingdom."],["D&C",90,17,"Be not ashamed, neither confounded; but be admonished in all your high-mindedness and pride, for it bringeth a snare upon your souls."],["D&C",90,18,"Set in order your houses; keep slothfulness and uncleanness far from you."],["D&C",90,19,"Now, verily I say unto you, let there be a place provided, as soon as it is possible, for the family of thy counselor and scribe, even Frederick G. Williams."],["D&C",90,20,"And let mine aged servant, Joseph Smith, Sen., continue with his family upon the place where he now lives; and let it not be sold until the mouth of the Lord shall name."],["D&C",90,21,"And let my counselor, even Sidney Rigdon, remain where he now resides until the mouth of the Lord shall name."],["D&C",90,22,"And let the bishop search diligently to obtain an agent, and let him be a man who has got riches in store—a man of God, and of strong faith—"],["D&C",90,23,"That thereby he may be enabled to discharge every debt; that the storehouse of the Lord may not be brought into disrepute before the eyes of the people."],["D&C",90,24,"Search diligently, pray always, and be believing, and all things shall work together for your good, if ye walk uprightly and remember the covenant wherewith ye have covenanted one with another."],["D&C",90,25,"Let your families be small, especially mine aged servant Joseph Smith's, Sen., as pertaining to those who do not belong to your families;"],["D&C",90,26,"That those things that are provided for you, to bring to pass my work, be not taken from you and given to those that are not worthy—"],["D&C",90,27,"And thereby you be hindered in accomplishing those things which I have commanded you."],["D&C",90,28,"And again, verily I say unto you, it is my will that my handmaid Vienna Jaques should receive money to bear her expenses, and go up unto the land of Zion;"],["D&C",90,29,"And the residue of the money may be consecrated unto me, and she be rewarded in mine own due time."],["D&C",90,30,"Verily I say unto you, that it is meet in mine eyes that she should go up unto the land of Zion, and receive an inheritance from the hand of the bishop;"],["D&C",90,31,"That she may settle down in peace inasmuch as she is faithful, and not be idle in her days from thenceforth."],["D&C",90,32,"And behold, verily I say unto you, that ye shall write this commandment, and say unto your brethren in Zion, in love greeting, that I have called you also to preside over Zion in mine own due time."],["D&C",90,33,"Therefore, let them cease wearying me concerning this matter."],["D&C",90,34,"Behold, I say unto you that your brethren in Zion begin to repent, and the angels rejoice over them."],["D&C",90,35,"Nevertheless, I am not well pleased with many things; and I am not well pleased with my servant William E. McLellin, neither with my servant Sidney Gilbert; and the bishop also, and others have many things to repent of."],["D&C",90,36,"But verily I say unto you, that I, the Lord, will contend with Zion, and plead with her strong ones, and chasten her until she overcomes and is clean before me."],["D&C",90,37,"For she shall not be removed out of her place. I, the Lord, have spoken it. Amen."]]);
